// Shared helper for the layout primitives (Stack/Grid/Container/LayoutGrid).
// Expands a responsive layout prop into `--sd-layout-<name>-<breakpoint>` custom
// properties, which each primitive's CSS consumes via a mobile-first fallback
// cascade. Breakpoints: small (0+, the base) → medium (768px) → large (1024px). Tier
// names match the Sys breakpoint ladder (tokens/sys/breakpoint.json) verbatim — one
// vocabulary, no md/lg abbreviations and no separate `base` key. See block-contract.md § Responsive.
import type { CSSProperties } from "react";

/** A layout value that can vary by breakpoint. A plain value applies at all widths;
 *  an object overrides per breakpoint (mobile-first: `small` is the base/mobile value,
 *  then `medium` at 768px, then `large` at 1024px). `medium`/`large` are optional —
 *  omit any tier to inherit the next-smaller one. */
export type Responsive<T> = T | { small?: T; medium?: T; large?: T };

/** Expands a responsive prop into inline `--sd-layout-<name>-<breakpoint>` custom
 *  properties. `toValue` maps each token/enum to its CSS value. */
export function responsiveVars<T>(
  name: string,
  value: Responsive<T> | undefined,
  toValue: (v: T) => string,
): CSSProperties {
  if (value === undefined || value === null) return {};
  const vars: Record<string, string> = {};
  if (typeof value === "object") {
    const responsive = value as { small?: T; medium?: T; large?: T };
    if (responsive.small !== undefined) vars[`--sd-layout-${name}-small`] = toValue(responsive.small);
    if (responsive.medium !== undefined) vars[`--sd-layout-${name}-medium`] = toValue(responsive.medium);
    if (responsive.large !== undefined) vars[`--sd-layout-${name}-large`] = toValue(responsive.large);
  } else {
    vars[`--sd-layout-${name}-small`] = toValue(value);
  }
  return vars as CSSProperties;
}
